-- Fakt kartochkalarining ruscha matni — 11-partiya:
-- Ismoil Somoniy, Husayn Boyqaro, Abulg'ozi Bahodirxon.

-- ===== Ismoil Somoniy =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Чьим именем названа династия Саманидов?', fact_ru = 'Я родился в 849 году в Фергане. Наша династия названа Саманидами по имени нашего предка Саманхудата.' WHERE id = 444;
UPDATE fact_cards SET topic_ru = 'Наместник Бухары', question_ru = 'С какого года Исмаил Самани стал наместником Мавераннахра?', fact_ru = 'Сначала я был назначен наместником города Бухары, а с 893 года стал наместником всего Мавераннахра.' WHERE id = 445;
UPDATE fact_cards SET topic_ru = 'Поход на Тараз', question_ru = 'На какой город Исмаил Самани совершил поход в 893 году?', fact_ru = 'В 893 году я совершил военный поход на город Тараз и вернулся с победой.' WHERE id = 446;
UPDATE fact_cards SET topic_ru = 'Единое государство', question_ru = 'Какой город был столицей государства, созданного Исмаилом Самани?', fact_ru = 'Я объединил весь Мавераннахр и создал единое сильное государство. Столицей моего государства был город Бухара.' WHERE id = 447;
UPDATE fact_cards SET topic_ru = 'Борьба за Хорасан', question_ru = 'Над кем одержал победу Исмаил Самани в борьбе за Хорасан?', fact_ru = 'В борьбе за Хорасан я одержал победу над Саффаридами и после этого стал самостоятельным правителем.' WHERE id = 448;
UPDATE fact_cards SET topic_ru = 'Справедливое правление', question_ru = 'Каким правителем считали Исмаила Самани его современники?', fact_ru = 'Современники считали меня мудрым и справедливым правителем: я покровительствовал учёным и богословам и возвёл много зданий.' WHERE id = 449;
UPDATE fact_cards SET topic_ru = 'Моё прозвище «амири мози»', question_ru = 'Что означает прозвище «амири мози»?', fact_ru = 'Последующие поколения с почтением называли меня «амири мози», то есть «минувший эмир».' WHERE id = 450;
UPDATE fact_cards SET topic_ru = 'Свидетельство Наршахи', question_ru = 'Сколько лет, по свидетельству Наршахи, правил Исмаил Самани?', fact_ru = 'Как пишет историк Наршахи, моё правление длилось 30 лет, и 20 лет из них я был также эмиром Хорасана.' WHERE id = 451;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда и где умер Исмаил Самани?', fact_ru = 'Я скончался в 907 году в своей столице — городе Бухаре.' WHERE id = 452;
UPDATE fact_cards SET topic_ru = 'Моя семья', question_ru = 'Кем были отец и брат Исмаила Самани?', fact_ru = 'Мой отец — Ахмад ибн Асад — был одним из правителей дома Саманидов. Мой брат Наср правил в Самарканде, а меня послал в Бухару.' WHERE id = 1657;
UPDATE fact_cards SET topic_ru = 'Моя столица Бухара', question_ru = 'Какой город был столицей государства Исмаила Самани?', fact_ru = 'Столицей нашего государства был город Бухара. В моё время Бухара расцвела и стала одним из красивейших городов Востока.' WHERE id = 1658;
UPDATE fact_cards SET topic_ru = 'Расцвет науки', question_ru = 'Каким центром стала Бухара во времена государства, основанного Исмаилом Самани?', fact_ru = 'При Саманидах Бухара стала центром науки и культуры. Дворцовая библиотека славилась по всему Востоку.' WHERE id = 1659;
UPDATE fact_cards SET topic_ru = 'Мои серебряные дирхемы', question_ru = 'Куда доходили серебряные монеты, чеканенные в государстве Исмаила Самани?', fact_ru = 'В нашем государстве чеканили серебряные дирхемы. С торговыми караванами эти монеты доходили до очень далёких краёв — даже до северных стран.' WHERE id = 1660;
UPDATE fact_cards SET topic_ru = 'Мавзолей Саманидов', question_ru = 'Какой памятник, построенный в Бухаре для династии Исмаила Самани, сохранился до наших дней?', fact_ru = 'В Бухаре до наших дней сохранился мавзолей Саманидов, возведённый для нашей династии. Это жемчужина зодчества, узорно выложенная из обожжённого кирпича.' WHERE id = 1661;
UPDATE fact_cards SET topic_ru = 'Грамота халифа', question_ru = 'Как багдадский халиф признал Исмаила Самани?', fact_ru = 'После моей победы в борьбе за Хорасан багдадский халиф прислал мне грамоту и признал меня правителем Мавераннахра и Хорасана.' WHERE id = 1662;
UPDATE fact_cards SET topic_ru = 'Моё имя сегодня', question_ru = 'Где сохранилось имя Исмаила Самани в наши дни?', fact_ru = 'Сегодня в соседнем Таджикистане денежная единица называется «сомони», а самая высокая вершина страны носит моё имя.' WHERE id = 1663;

-- ===== Husayn Boyqaro =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Хусейн Байкара?', fact_ru = 'Я родился в 1438 году в Герате. Моё полное имя — Хусейн ибн Мирза Мансур ибн Мирза Байкара.' WHERE id = 347;
UPDATE fact_cards SET topic_ru = 'Восшествие на престол', question_ru = 'С какого года Хусейн Байкара правил хорасанским престолом?', fact_ru = 'С 1469 года я правил хорасанским престолом и укрепил Герат.' WHERE id = 348;
UPDATE fact_cards SET topic_ru = 'Моё правление', question_ru = 'Сколько лет Хусейн Байкара правил Хорасаном?', fact_ru = 'Хорасаном я правил с 1469 по 1506 год — почти сорок лет.' WHERE id = 349;
UPDATE fact_cards SET topic_ru = 'Мой псевдоним', question_ru = 'Под каким псевдонимом Хусейн Байкара писал свои стихи?', fact_ru = 'Свои стихи я писал под псевдонимом «Хусайни».' WHERE id = 350;
UPDATE fact_cards SET topic_ru = 'Мой диван', question_ru = 'Сколько газелей вошло в диван Хусейна Байкары?', fact_ru = 'В мой диван вошло около 200 газелей, мухаммасов и рубаи; есть у меня и стихи на фарси.' WHERE id = 351;
UPDATE fact_cards SET topic_ru = 'Мой друг Навои', question_ru = 'На какую должность Хусейн Байкара назначил Алишера Навои?', fact_ru = 'Моего друга Алишера Навои я особой грамотой вызвал из Самарканда и назначил хранителем печати.' WHERE id = 352;
UPDATE fact_cards SET topic_ru = 'Герат — центр культуры', question_ru = 'Каким городом стал Герат во времена Хусейна Байкары?', fact_ru = 'В моё время Герат стал крупным культурным центром Востока: я поддерживал учёных, поэтов и ремесленников.' WHERE id = 353;
UPDATE fact_cards SET topic_ru = 'Мои постройки', question_ru = 'Какие здания возвёл Хусейн Байкара?', fact_ru = 'Я велел построить медресе, караван-сараи, мосты и мечети.' WHERE id = 354;
UPDATE fact_cards SET topic_ru = 'Заказ Бехзаду', question_ru = 'Какому живописцу Хусейн Байкара поручил создание миниатюр?', fact_ru = 'Живописцу Камалиддину Бехзаду я поручил создать новые миниатюры.' WHERE id = 355;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда умер Хусейн Байкара и где он погребён?', fact_ru = 'Я скончался в 1506 году; погребён в усыпальнице медресе, построенного мной самим.' WHERE id = 356;
UPDATE fact_cards SET topic_ru = 'Моя родословная Тимуридов', question_ru = 'Представителем какой династии был Хусейн Байкара?', fact_ru = 'Я из дома Тимуридов: моя родословная через Умаршайха Мирзу восходит к сахибкирану Амиру Темуру.' WHERE id = 1623;
UPDATE fact_cards SET topic_ru = 'Мои стихи на тюркском', question_ru = 'На каком языке Хусейн Байкара писал свои стихи?', fact_ru = 'Свои стихи я писал на родном тюркском языке. Я всем сердцем верил в красоту и богатство этого языка.' WHERE id = 1624;
UPDATE fact_cards SET topic_ru = 'Мой труд «Рисоля»', question_ru = 'Какое прозаическое произведение написал Хусейн Байкара?', fact_ru = 'В прозе я написал труд под названием «Рисоля». В нём я высоко оценил наш родной язык и творчество современников, особенно заслуги моего друга Алишера Навои.' WHERE id = 1625;
UPDATE fact_cards SET topic_ru = 'Моё почтение к Джами', question_ru = 'Какой великий поэт пользовался большим почётом при дворе Хусейна Байкары?', fact_ru = 'При моём дворе большим почётом пользовался великий поэт Абдурахман Джами. Я считал его наставником и прислушивался к его советам.' WHERE id = 1626;
UPDATE fact_cards SET topic_ru = 'Историки моего двора', question_ru = 'Какие знаменитые историки творили в Герате во времена Хусейна Байкары?', fact_ru = 'В моё время в Герате творили знаменитые историки Мирхонд и Хондамир. Написанные ими книги донесли события прошлого до наших дней.' WHERE id = 1627;
UPDATE fact_cards SET topic_ru = 'Моё доверие к Навои', question_ru = 'Куда Хусейн Байкара призвал Алишера Навои, взойдя на престол, и на какие должности его назначил?', fact_ru = 'Взойдя на престол, я призвал в Герат своего школьного друга Алишера Навои и назначил его на высокие государственные должности. Он стал для меня самым надёжным советником.' WHERE id = 1628;
UPDATE fact_cards SET topic_ru = 'Я в «Маджолис ун-нафоис»', question_ru = 'В каком произведении Алишера Навои отведено особое место творчеству Хусейна Байкары?', fact_ru = 'Мой друг Алишер Навои отвёл мне особое место в произведении «Маджолис ун-нафоис» и высоко оценил мои стихи.' WHERE id = 1629;

-- ===== Abulg'ozi Bahodirxon =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Кем был отец Абулгази Бахадурхана?', fact_ru = 'Я один из семи сыновей хивинского хана Арабмухаммадхана. В учебнике годом моего рождения указан 1603-й.' WHERE id = 402;
UPDATE fact_cards SET topic_ru = 'Восшествие на престол', question_ru = 'С какого года Абулгази Бахадурхан правил Хивинским ханством?', fact_ru = 'Хивинским ханством я правил с 1645 года.' WHERE id = 403;
UPDATE fact_cards SET topic_ru = 'Моё правление', question_ru = 'Сколько лет Абулгази Бахадурхан правил Хивой?', fact_ru = 'Хивой я правил с 1645 по 1663 год, затем передал престол сыну.' WHERE id = 404;
UPDATE fact_cards SET topic_ru = '«Шаджарайи турк»', question_ru = 'О чём труд Абулгази Бахадурхана «Шаджарайи турк»?', fact_ru = 'Я написал свой труд «Шаджарайи турк» — в нём изложена история тюркских народов.' WHERE id = 405;
UPDATE fact_cards SET topic_ru = 'Мой труд как источник', question_ru = 'С какой целью учёные обращаются к труду «Шаджарайи турк»?', fact_ru = 'Учёные пользуются «Шаджарайи турк» как историческим источником.' WHERE id = 406;
UPDATE fact_cards SET topic_ru = 'Хан и учёный', question_ru = 'Кем ещё, кроме государственного деятеля, известен Абулгази Бахадурхан?', fact_ru = 'Я известен не только как государственный деятель, но и как учёный.' WHERE id = 407;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда умер Абулгази Бахадурхан?', fact_ru = 'Я скончался в 1664 году.' WHERE id = 408;
UPDATE fact_cards SET topic_ru = '«Шаджарайи тарокима»', question_ru = 'Какой труд по истории туркмен написал Абулгази Бахадурхан?', fact_ru = 'Кроме «Шаджарайи турк» я написал и труд под названием «Шаджарайи тарокима». В нём я рассказал о происхождении и родословной туркменского народа.' WHERE id = 1478;
UPDATE fact_cards SET topic_ru = 'Мои годы в Исфахане', question_ru = 'В каком городе Абулгази Бахадурхан прожил около десяти лет, изучая книги по истории?', fact_ru = 'В молодости из-за распрей за престол я оказался в Иране и прожил около десяти лет в городе Исфахан. Там я много читал книги по истории на персидском языке и умножал свои знания.' WHERE id = 1479;
UPDATE fact_cards SET topic_ru = 'Знание языков', question_ru = 'Какими языками владел Абулгази Бахадурхан?', fact_ru = 'Кроме тюркского я хорошо знал персидский и арабский языки. Исторические сочинения на этих языках я читал в подлиннике.' WHERE id = 1480;
UPDATE fact_cards SET topic_ru = 'Как я писал — простым языком', question_ru = 'На каком языке писал свои произведения Абулгази Бахадурхан?', fact_ru = 'Свои труды я писал на простом тюркском языке, понятном каждому. Я нарочно не употреблял трудных арабских и персидских слов и вёл рассказ на языке, понятном народу.' WHERE id = 1481;
UPDATE fact_cards SET topic_ru = 'Мой род', question_ru = 'К какой династии принадлежал Абулгази Бахадурхан?', fact_ru = 'Я из династии Шейбанидов — наш род восходит к потомкам Чингисхана. Потому я хорошо знал историю родословных.' WHERE id = 1482;
UPDATE fact_cards SET topic_ru = 'Источники, которыми я пользовался', question_ru = 'Каким знаменитым источником пользовался Абулгази Бахадурхан при написании «Шаджарайи турк»?', fact_ru = 'При написании «Шаджарайи турк» я пользовался древними историческими источниками, в том числе трудом Рашид ад-Дина «Джами ат-таварих».' WHERE id = 1483;
UPDATE fact_cards SET topic_ru = 'Завершение моего труда', question_ru = 'При ком был завершён труд Абулгази Бахадурхана «Шаджарайи турк»?', fact_ru = 'Довести «Шаджарайи турк» до конца я не успел. Его завершили учёные при моём сыне Анушахане.' WHERE id = 1484;
UPDATE fact_cards SET topic_ru = 'Мои переводы в Европе', question_ru = 'На какие языки переведён труд Абулгази Бахадурхана «Шаджарайи турк»?', fact_ru = 'Мой труд «Шаджарайи турк» был позже переведён на европейские языки — немецкий, французский и русский. Он стал для учёных важным источником в изучении истории Востока.' WHERE id = 1485;
UPDATE fact_cards SET topic_ru = 'Мой труд по врачеванию', question_ru = 'Какое медицинское сочинение приписывают Абулгази Бахадурхану?', fact_ru = 'Кроме истории я интересовался и врачеванием. Мне приписывают также медицинское сочинение «Манофе ул-инсон» — в нём речь идёт о лекарствах и их пользе.' WHERE id = 1486;
UPDATE fact_cards SET topic_ru = 'Почему я взялся писать историю', question_ru = 'По какой причине Абулгази Бахадурхан решил писать историю?', fact_ru = 'В моё время в Хорезме не нашлось историка, хорошо знающего события прошлого, и потому я решил написать историю своего народа сам.' WHERE id = 1487;
